import {BENCHMARKS,validateBenchmarkReport,summarizeReport} from './benchmarks.js';
import {catalog,dimensions,evidenceFor,reviewedOn,documentSummary} from './technology.js';
import {demo,clone,TYPES,validateState,platformMetrics,scorePlatforms,decision,normalizedMix,requirementReview} from './core.js';
const KEY='basis-iris-production-v1';
const EVALUATION_KEYS=[KEY,'basis-latest-agent-result','basis-community-benchmark-imports','basis-swe-config','basis-evaluation-repo','basis-evidence-exclusions'];
let s;try{s=JSON.parse(localStorage.getItem(KEY));if(!validateState(s))throw Error('Invalid');}catch{s=clone(demo)}
let page='overview',filter='All',selected=s.platforms[0]?.id,drawer=false,details=false,notice='';
const $=x=>document.querySelector(x);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const f=(x,d=0)=>x==null?'—':Number(x).toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d});const money=x=>x==null?'—':'$'+f(x,0);const pct=x=>x==null?'—':f(x*100,1)+'%';const safeHref=u=>/^https:\/\/[^\s]+$/i.test(String(u||''))?esc(u):'#';const icon=(n,size=18)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="#i-${n}"></use></svg>`;
const icons=`<svg width="0" height="0" style="position:absolute;overflow:hidden"><defs>${Object.entries({users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v3"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',folder:'<path d="M3 7V5h6l2 2h10v13H3Z"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',terminal:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 8 4 4-4 4m7 0h3"/>',play:'<path d="m8 5 11 7-11 7Z"/>',spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',finger:'<path d="M12 11v3m-4-2v2a4 4 0 0 0 8 0v-2a4 4 0 1 0-8 0ZM5 13V9a7 7 0 0 1 14 0v4M3 15V9a9 9 0 0 1 18 0v6M12 19v2"/>',shield:'<path d="m12 2 9 4v6c0 5-3.5 8-9 10-5.5-2-9-5-9-10V6z"/><path d="m8 12 3 3 5-6"/>',flask:'<path d="M9 3h6m-5 0v6l-5.6 9.5A2 2 0 0 0 6 21h12a2 2 0 0 0 1.6-2.5L14 9V3M7 16h10"/>',bars:'<path d="M5 20V10m7 10V4m7 16v-7"/>',scale:'<path d="M12 3v18M5 7h14M5 7 2 13h6L5 7Zm14 0-3 6h6l-3-6ZM8 21h8"/>',brain:'<path d="M12 18V6a4 4 0 0 0-8 0 4 4 0 0 0-1 7 4 4 0 0 0 4 6 4 4 0 0 0 5-1Zm0 0V6a4 4 0 0 1 8 0 4 4 0 0 1 1 7 4 4 0 0 1-4 6 4 4 0 0 1-5-1Z"/>',chev:'<path d="m9 18 6-6-6-6"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m4 12 5 5L20 6"/>',warning:'<path d="m12 3 10 18H2L12 3Zm0 7v4m0 3h.01"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',download:'<path d="M12 3v14m-5-5 5 5 5-5M4 17v4h16v-4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',trash:'<path d="M4 7h16M10 7V4h4v3m-8 0 1 14h10l1-14M10 11v6m4-6v6"/>',link:'<path d="M10 14a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 10a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',book:'<path d="M4 5h7a3 3 0 0 1 3 3v13a3 3 0 0 0-3-3H4zM20 5h-4a3 3 0 0 0-3 3v13a3 3 0 0 1 3-3h4z"/>',rotate:'<path d="M3 12a9 9 0 1 0 3-7M3 4v5h5"/>',cross:'<path d="M5 5l14 14m0-14L5 19"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'}).map(([n,d])=>`<g id="i-${n}">${d}</g>`).join('')}</defs></svg>`;
function save(){if(workspaceLocked())return;s.meta.lastUpdated=new Date().toISOString().slice(0,10);localStorage.setItem(KEY,JSON.stringify(s));queueWorkspaceSave();}function note(t){notice=t;render();setTimeout(()=>{notice='';const n=$('#toast');if(n)n.remove()},3200)}
const nav=[['runs','Runs','grid'],['overview','Home','grid'],['org','Team context','finger'],['pilot','Tasks & Benchmarks','flask'],['gates','Services','shield'],['record','Run evaluation','play'],['pilotResults','Pilot results','book'],['results','Evaluation results','bars'],['compare','Pilot comparison','bars'],['technology','Tool catalog','book'],['benchmarks','External benchmarks','book'],['judge','Review quality','shield'],['decision','Decision summary','scale'],['settings','Settings','settings']];
const stages=[
 {label:'Set up',icon:'settings',pages:['gates','org','pilot'],hint:'Choose services, describe your team, then define tasks.'},
 {label:'Run evaluation',icon:'play',pages:['record'],hint:'Review setup, add optional benchmarks, and execute locally.'},
 {label:'Results',icon:'bars',pages:['results'],hint:'Inspect saved runs, compare evidence, and review requirements.'}
];
function stageFor(id){return stages.find(g=>g.pages.includes(id))}
function sidebarNav(){if(workspaceReady)return workspaceNav();const items=[['overview','Home','grid'],...stages.map(g=>[g.pages[0],g.label,g.icon]),['technology','Tool catalog','book'],['settings','Settings','settings']];return items.map(([id,label,i],n)=>`${n===4?'<div class="sidetitle nav-resources">RESOURCES</div>':''}<button class="navitem ${(page===id||stageFor(id)?.pages.includes(page))?'active':''}" data-nav="${id}" ${(page===id||stageFor(id)?.pages.includes(page))?'aria-current="page"':''}>${icon(i,18)}<span>${label}</span></button>`).join('')}
function stageNavigation(){if(workspaceReady&&!workspaceRun)return '';const g=stageFor(page);if(!g||g.pages.length<2)return '';return `<div class="stage-navigation"><nav aria-label="${g.label} sections">${g.pages.map(id=>`<button data-nav="${id}" ${id===page?'aria-current="page"':''} class="${id===page?'chosen':''}">${esc(nav.find(n=>n[0]===id)[1])}</button>`).join('')}</nav><p>${g.hint}</p></div>`}
function storedEvidence(){if(workspaceReady&&workspaceRun)return s.importedEvidence||{agent:null,reports:[]};let agent=null,reports=[];try{agent=JSON.parse(localStorage.getItem('basis-latest-agent-result')||'null')}catch{}try{const data=(workspaceReady&&workspaceRun?s.importedEvidence?.reports||[]:JSON.parse(localStorage.getItem('basis-community-benchmark-imports')||'[]'));if(Array.isArray(data))reports=data}catch{}return {agent,reports}}

function shell(content){return `${icons}<div class="shell"><aside class="side ${drawer?'show':''}"><div class="brand"><svg class="brand-symbol" aria-hidden="true" viewBox="0 0 48 48"><path d="M24 9v30M9 24h30M13.4 13.4l21.2 21.2m0-21.2L13.4 34.6" fill="none" stroke="#bc9cef" stroke-width="3.4"/></svg><div><b>basis<span class="dot">.</span></b></div></div><div class="sidetitle">EVALUATION</div><nav aria-label="Main navigation">${sidebarNav()}</nav><div class="sidebottom" ${workspaceReady?'hidden':''}><div class="smallcaps">CURRENT EVALUATION</div><strong>${esc(s.meta.name)}</strong><div class="tiny">${s.platforms.filter(x=>x.enabled).length} services · ${s.platforms.filter(x=>x.enabled).reduce((n,p)=>n+selectedModels(p).length,0)} models</div><div class="sideactions"><button title="Export study" data-act="export">${icon('download',16)}</button><button title="Import study" data-act="import">${icon('upload',16)}</button><button title="Reset local evaluation" aria-label="Reset local evaluation" data-act="reset">${icon('rotate',16)}</button></div></div></aside><main class="main ${workspaceReady&&workspaceRun&&page!=='runs'?'run-scoped':''} ${requiresLocal()?'local-required-main':''}"><header class="top"><button class="mobilemenu" data-act="menu" aria-label="Toggle menu">${icon('menu')}</button><div class="crumb">WORKSPACE <span>/</span> ${esc(page==='runs'?'Runs':stageFor(page)?.label||nav.find(x=>x[0]===page)?.[1])}</div><div class="topright"><span class="studyflag ${s.meta.demo?'demo':''}">${s.meta.demo?'● DEMONSTRATION DATA':'● RECORDED DATA (UNVERIFIED)'}</span><button class="helpbtn" data-act="assistant" aria-label="Help">${icon('info',16)} <span>Help</span></button></div></header><div class="workspace ${requiresLocal()?'local-required-workspace':''}">${workspaceReady?workspaceHeader():''}${stageNavigation()}${workspaceLocked()&&['gates','org','pilot'].includes(page)?`<fieldset class="frozen-setup" disabled>${content}</fieldset>`:content}</div><footer>Basis / Evidence before preference <span>${workspaceReady?'Runs saved on this computer':'Setup stays in this browser · Local runs stay on this computer'}</span></footer></main></div>${drawer?'<button class="backdrop" data-act="menu" aria-label="Close menu"></button>':''}${notice?`<div id="toast" role="status">${esc(notice)}</div>`:''}<input type="file" id="file-input" accept=".json,application/json" hidden>`}
function title(k,h,desc,action=''){const group=stageFor(page);if(group)k=`0${stages.indexOf(group)+1} / ${group.label.toUpperCase()}`;return `<div class="eyebrow"><span class="pin"></span>${k}</div><div class="pageheading"><div><h1>${h}</h1><p>${desc}</p></div>${action}</div>`}
function platformName(id){return s.platforms.find(p=>p.id===id)?.name||id}function selectOptions(items,v){return items.map(([value,text])=>`<option value="${esc(value)}" ${String(value)===String(v)?'selected':''}>${esc(text)}</option>`).join('')}
function stat(v,l,d){return `<div class="metric"><div class="m-label">${l}</div><strong>${v}</strong><span>${d}</span></div>`}
function overview(){
 const {reports}=storedEvidence(),hasEvidence=!!(s.runs.length||reports.length);
 return title('START HERE','Compare coding tools, step by step.','Prepare your evaluation, collect results, and compare the evidence.')+`
 <section class="start-panel"><div class="start-copy"><span class="miniTag">Your evaluation</span><h2>Start with your team’s work</h2><p>Choose the services you want to evaluate and define what successful work looks like.</p><button class="primary" data-nav="gates">Set up an evaluation ${icon('chev',16)}</button></div><ol class="start-checklist"><li><span>1</span><div><b>Set up</b><small>Select services, requirements, tasks, and credentials.</small></div></li><li><span>2</span><div><b>Run evaluation</b><small>Execute tasks and optional benchmarks locally.</small></div></li><li><span>3</span><div><b>Review results</b><small>Compare services against the criteria you defined.</small></div></li></ol></section>
 <div class="journey-grid"><button class="journey-card" data-nav="gates"><span class="journey-number">01 / SET UP</span><h3>Prepare your evaluation</h3><p>Define your team context, requirements, and tasks.</p><span class="journey-link">Open setup ${icon('chev',16)}</span></button><button class="journey-card" data-nav="record"><span class="journey-number">02 / RUN EVALUATION</span><h3>Collect real evidence</h3><p>Execute tasks and optional benchmark packs locally.</p><span class="journey-link">Open Run evaluation ${icon('chev',16)}</span></button><button class="journey-card" data-nav="results"><span class="journey-number">03 / RESULTS</span><h3>Review what happened</h3><p>${hasEvidence?'Review recorded observations and benchmark reports.':'Run an evaluation to compare service outcomes against your saved setup.'}</p><span class="journey-link">Open results ${icon('chev',16)}</span></button></div>`;
}

function profileValue(path){const [group,key]=path.split('.');const value=s[group][key];return !s.meta.editedFields?.includes(path)&&value===demo[group][key]?'':esc(value)}
function legacyOrg(){const o=s.org;return title('02 / CONTEXT','Team context','Describe the team and workload you want to evaluate.',`<button class="secondary" data-act="assistant">${icon('spark',16)} Guided discovery</button>`)+`<div class="split"><div class="panel"><div class="panelheading"><h3>Organization profile</h3><span class="miniTag">Editable</span></div><div class="formgrid"><label>Organization<input data-path="meta.name" placeholder="New organization study" value="${profileValue('meta.name')}"></label><label>Engineers<input type="number" min="1" data-path="org.developers" placeholder="0" value="${profileValue('org.developers')}"></label><label>Blended hourly cost ($)<input type="number" min="0" data-path="org.rate" placeholder="0" value="${profileValue('org.rate')}"></label><label>Monthly AI budget ($)<input type="number" min="0" data-path="org.budget" placeholder="0" value="${profileValue('org.budget')}"></label><label>Risk profile<select data-path="org.risk" data-placeholder-value="unassessed">${selectOptions([['unassessed','Select risk profile'],['high','High governance'],['medium','Standard governance'],['low','Experimental']],o.risk)}</select></label><label>Repository profile<input data-path="org.repoSize" placeholder="Not provided" value="${profileValue('org.repoSize')}"></label></div><label class="fullfield">Languages / frameworks (comma separated)<input data-path="org.stack" placeholder="e.g. TypeScript, Python, React" value="${esc(o.stack.join(', '))}"></label><label class="fullfield">Primary objective<textarea data-path="org.objective" placeholder="Describe what you want to improve">${profileValue('org.objective')}</textarea></label><label class="fullfield">Data boundaries<textarea data-path="org.privacy" placeholder="Describe your data and privacy requirements">${profileValue('org.privacy')}</textarea></label></div><div class="panel"><div class="panelheading"><h3>Workload signature</h3><span class="miniTag">Adjust the mix</span></div><p class="muted">How is your team's engineering time distributed? These weights drive the task-adjusted comparisons.</p><div class="mixbars">${TYPES.map((t,i)=>`<div class="mixrow"><div class="mixhead"><span><i class="mixdot" style="background:var(--c${i+1})"></i>${t}</span><b data-mix-label="${t}">${s.mix[t]}%</b></div><input aria-label="${t} workload share" type="range" min="0" max="100" data-mix="${t}" value="${s.mix[t]}" style="accent-color:var(--c${i+1})"></div>`).join('')}</div><div class="panelnote" id="mixnote">Normalized for comparison: ${Math.round(Object.values(s.mix).reduce((a,b)=>a+Number(b),0))}% entered (automatically normalized).</div><div class="miniCall">${icon('info',18)} <span>Profile inputs are self-reported unless verified by linked evidence. No repository has been analyzed.</span></div></div></div><div class="panel focus"><h3>Decision priorities</h3><p class="muted">Weights influence exploratory scores. Required gates cannot be overridden by a high score.</p><div class="weightrow">${Object.entries(s.weights).map(([k,v])=>`<label>${k[0].toUpperCase()+k.slice(1)} <input type="number" min="0" max="100" data-weight="${k}" value="${v}"> <small>%</small></label>`).join('')}</div></div>`}
const pendingKeys=new Map();
const isLocalApp=()=>['localhost','127.0.0.1'].includes(location.hostname);
function serviceKey(p){return p.id==='opencode'?(modelProvider(p)==='anthropic'?'ANTHROPIC_API_KEY':'OPENAI_API_KEY'):localRunners[p.id]||null}
function serviceKeyField(p){const key=serviceKey(p);return key?`<div class="service-key-field"><div class="key-field-heading"><label for="key-${esc(p.id)}">API key</label><span class="pill unverified" data-key-status="${key}">Checking…</span></div><div class="credential-entry"><input id="key-${esc(p.id)}" type="password" aria-label="${esc(p.name)} API key" autocomplete="new-password" data-local-key="${key}" placeholder="API key" ${isLocalApp()?'disabled':''}>${isLocalApp()?`<button class="secondary" data-save-local="${key}" disabled>Save key</button>`:''}</div><p class="credential-feedback" role="status" data-key-feedback="${key}"></p></div>`:`<p class="service-config-note">${p.id==='opencode'?'Choose a provider/model to configure its key.':'Automatic execution is not available for this service.'}</p>`}
function setupHandoff(){return `<div class="org-continue">${page==='gates'?`<button class="primary" data-nav="org">Continue to team context ${icon('chev',16)}</button>`:`<button class="primary" data-act="continue-local">${isLocalApp()?'Continue to evaluation':'Continue locally'} ${icon('chev',16)}</button>`}</div><p id="handoff-feedback" role="status"></p>`}
function continueToTasks(){return `<div class="org-continue"><button class="primary" data-nav="pilot">Continue to tasks &amp; benchmarks ${icon('chev',16)}</button></div>`}

const modelCatalogs=new Map();
function modelProvider(p){return p.id==='opencode'?(p.modelProvider|| (p.model?.startsWith('anthropic/')?'anthropic':'openai')):({codex:'openai',claude:'anthropic',cursor:'cursor'}[p.id]||'');}
function modelCatalogKey(p){return p.id+':'+modelProvider(p);}
function selectedModels(p){return Array.isArray(p.models)?[...new Set(p.models.filter(m=>typeof m==='string'&&m&&!/^Specify /.test(m)))]:p.model&&!/^Specify /.test(p.model)?[p.model]:[];}
function candidateKey(p){return p.candidateId||p.agent||p.id;}
function attemptKey(r){return `${r.taskIndex}:${candidateKey(r)}`;}
function candidateName(p){return p.model?`${p.name} · ${p.model}`:p.name;}
function serviceModelField(p){
 const supported=!!modelProvider(p),catalog=modelCatalogs.get(modelCatalogKey(p));
 const connected=isLocalApp()&&bridgeReady&&localStatus?.configured?.[serviceKey(p)];
 const ready=connected&&catalog?.status==='ready'&&catalog.models.length>0;
 const canAdd=ready&&catalog.models.some(m=>!selectedModels(p).includes(m.id));
 const placeholder=!supported?'Managed by service':!isLocalApp()?'Continue locally to load models':!connected?'Save a key first':catalog?.status==='loading'?'Loading models…':catalog?.status==='error'?'Models unavailable':catalog?.status==='ready'&&!catalog.models.length?'No models returned':ready&&!canAdd?'All available models selected':selectedModels(p).length?'Add another model':'Select a model';
 const message=catalog?.status==='error'?catalog.error:ready&&selectedModels(p).some(model=>!catalog.models.some(m=>m.id===model))?'Previous selection is unavailable. Choose a returned model.':'';
 return `<div class="model-field-heading"><label for="model-${esc(p.id)}">Models</label>${supported?`<button class="iconbtn" type="button" data-refresh-models="${esc(p.id)}" aria-label="Refresh ${esc(p.name)} models" title="${esc(catalog?.fetchedAt?`Fetched from ${catalog.source} at ${catalog.fetchedAt}. Refresh models.`:'Refresh models')}" ${!connected||catalog?.status==='loading'?'disabled':''}>${icon('rotate',14)}</button>`:''}</div><select id="model-${esc(p.id)}" data-service-model="${esc(p.id)}" aria-label="${esc(p.name)} model" data-placeholder-value="" ${!canAdd?'disabled':''}><option value="" disabled selected>${esc(placeholder)}</option>${ready?catalog.models.map(m=>`<option value="${esc(m.id)}" ${selectedModels(p).includes(m.id)?'disabled':''}>${esc(m.name===m.id?m.id:m.name+' · '+m.id)}</option>`).join(''):''}</select><div class="selected-models">${selectedModels(p).map(model=>`<div class="selected-model"><span>${esc(model)}</span><button type="button" class="iconbtn" data-remove-model="${esc(model)}" data-model-service="${esc(p.id)}" aria-label="Remove ${esc(model)} from ${esc(p.name)}">${icon('cross',14)}</button></div>`).join('')}</div><p class="model-feedback" role="status">${esc(message)}</p>`;
}
function paintModelFields(){
 if(activeDropdown?.trigger?.closest('[data-model-control]'))closeDropdown();
 document.querySelectorAll('[data-model-control]').forEach(holder=>{const p=s.platforms.find(p=>p.id===holder.dataset.modelControl);if(p)holder.innerHTML=serviceModelField(p)});
 enhanceSelects();bindModelFields();
}
function bindModelFields(){
 document.querySelectorAll('[data-remove-model]').forEach(b=>b.onclick=()=>{const p=s.platforms.find(p=>p.id===b.dataset.modelService);p.models=selectedModels(p).filter(m=>m!==b.dataset.removeModel);p.model=p.models[p.models.length-1]||'';save();paintModelFields()});
 document.querySelectorAll('[data-service-model]').forEach(el=>el.onchange=()=>{const p=s.platforms.find(p=>p.id===el.dataset.serviceModel),catalog=modelCatalogs.get(modelCatalogKey(p));if(catalog?.status==='ready'&&catalog.models.some(m=>m.id===el.value)){const models=selectedModels(p);if(!models.includes(el.value)&&models.length>=10){showMessage('Choose up to ten models per service.');paintModelFields();return}p.models=[...new Set([...models,el.value])];p.model=el.value;save();paintModelFields()}});
 document.querySelectorAll('[data-refresh-models]').forEach(el=>el.onclick=()=>loadServiceModels(s.platforms.find(p=>p.id===el.dataset.refreshModels),true));
 document.querySelectorAll('[data-model-provider]').forEach(el=>el.onchange=()=>{const p=s.platforms.find(p=>p.id===el.dataset.modelProvider);p.modelProvider=el.value;p.model='';p.models=[];save();render()});
}
async function loadServiceModels(p,force=false){
 const key=modelCatalogKey(p),existing=modelCatalogs.get(key);
 if(!modelProvider(p)||!isLocalApp()||!bridgeReady||!localStatus?.configured?.[serviceKey(p)])return;
 if(!force&&existing&&(existing.status==='loading'||Date.now()-existing.time<60000))return;
 const entry={status:'loading',models:[],time:Date.now()};modelCatalogs.set(key,entry);paintModelFields();
 try{const result=await localRequest('models',{service:p.id,provider:modelProvider(p)});if(!Array.isArray(result.models))throw Error('Update and restart the local companion to load models.');if(modelCatalogs.get(key)!==entry)return;Object.assign(entry,result,{status:'ready',time:Date.now()});}
 catch(error){if(modelCatalogs.get(key)!==entry)return;Object.assign(entry,{status:'error',error:error.message,models:[],time:Date.now()})}
 paintModelFields();if(page==='record')refreshEvaluationReadiness();
}
function invalidateModels(secret){const provider={OPENAI_API_KEY:'openai',ANTHROPIC_API_KEY:'anthropic',CURSOR_API_KEY:'cursor'}[secret];for(const key of modelCatalogs.keys())if(key.endsWith(':'+provider))modelCatalogs.delete(key);paintModelFields();}
function serviceSelection(){return `<section class="panel service-selection" aria-labelledby="services-heading"><div class="panelheading"><div><span class="smallcaps">1 / SERVICES</span><h3 id="services-heading">Models & keys</h3></div><button class="secondary" data-act="manage-platforms">${icon('plus',16)} Add custom service</button></div><div class="service-configurations">${s.platforms.filter(p=>p.enabled).map(p=>`<section class="service-configuration" data-config-service="${esc(p.id)}" aria-label="${esc(p.name)} configuration"><div class="service-config-heading"><div><h3>${esc(p.name)}</h3><span class="muted">${esc(p.provider||'Custom service')}</span></div><button class="iconbtn" type="button" data-act="toggle-service" data-id="${esc(p.id)}" aria-pressed="true" aria-label="Remove ${esc(p.name)} from evaluation" title="Remove service">${icon('cross',16)}</button></div>${p.id==='opencode'?`<label class="model-provider">Provider<select data-model-provider="opencode" aria-label="OpenCode provider">${selectOptions([['openai','OpenAI'],['anthropic','Anthropic']],modelProvider(p))}</select></label>`:''}<div class="service-config-fields"><div data-service-key="${esc(p.id)}">${serviceKeyField(p)}</div><div class="service-model-field" data-model-control="${esc(p.id)}">${serviceModelField(p)}</div></div></section>`).join('')||'<p class="muted">Choose a service below to get started.</p>'}</div><div class="available-services">${s.platforms.filter(p=>!p.enabled).map(p=>`<button class="secondary" data-act="toggle-service" data-id="${esc(p.id)}" aria-pressed="false" aria-label="Include ${esc(p.name)} in evaluation">${icon('plus',14)} ${esc(p.name)}</button>`).join('')}</div></section>`}
function continueLocally(){
 if(isLocalApp()){page='record';if(workspaceReady)localStorage.setItem('basis-run-page',page);render();return}
 // Include unsaved visible entries, so the handoff never silently drops a typed key.
 document.querySelectorAll('[data-local-key]').forEach(input=>{if(input.value.trim())pendingKeys.set(input.dataset.localKey,input.value.trim())});
 const allowed=new Set(neededProviders().map(p=>p.secret));
 const keys=Object.fromEntries([...pendingKeys].filter(([key])=>allowed.has(key)));
 if(Object.values(keys).some(value=>value.length<8||value.length>8000||/[\r\n\x00]/.test(value))){showMessage('Enter a valid single-line API key before continuing.');return}
 const targetOrigin='http://127.0.0.1:8765',nonce=Array.from(crypto.getRandomValues(new Uint32Array(4)),x=>x.toString(16).padStart(8,'0')).join('');
 let popup,timeout,complete=false;
 const feedback=message=>{if($('#handoff-feedback'))$('#handoff-feedback').textContent=message};
 const cleanup=()=>{clearTimeout(timeout);window.removeEventListener('message',receive)};
 const receive=event=>{if(event.origin!==targetOrigin||event.source!==popup||event.data?.nonce!==nonce)return;
  if(event.data.type==='basis-setup-ready'&&!complete){complete=true;popup.postMessage({type:'basis-setup-transfer',nonce,setup:clone(s),keys},targetOrigin);feedback('Finish in the local tab.');clearTimeout(timeout)}
  if(event.data.type==='basis-setup-complete'){pendingKeys.clear();document.querySelectorAll('[data-local-key]').forEach(input=>input.value='');updateLocalStatus();feedback('Setup transferred. Continue in the local tab.');cleanup()}
  if(event.data.type==='basis-setup-error'){feedback('Transfer was not completed. Your setup is still here.');cleanup()}
 };
 window.addEventListener('message',receive);
 popup=window.open(`${targetOrigin}/#setup-transfer=${nonce}`,'_blank');
 if(!popup){cleanup();feedback('Allow the local-app window, then try again.');return}
 feedback('Opening the local app in a new tab…');
 timeout=setTimeout(()=>{cleanup();feedback('Local app not available. Start it using Connection help, then try again.');},15000);
}
let receivingSetup=false;
function receiveLocalSetup(){
 if(!isLocalApp()||!window.opener)return;
 const nonce=new URLSearchParams(location.hash.slice(1)).get('setup-transfer');
 if(!/^[a-f0-9]{4,128}$/.test(nonce||''))return;
 receivingSetup=true;history.replaceState(null,'',location.pathname+location.search);
 const source=window.opener,origin='https://pouyanjay.github.io';let processing=false;
 const reply=type=>source.postMessage({type,nonce},origin);
 const receive=async event=>{if(processing||event.source!==source||event.origin!==origin||event.data?.nonce!==nonce||event.data.type!=='basis-setup-transfer')return;
  processing=true;clearInterval(readyTimer);window.removeEventListener('message',receive);
  try{const {setup,keys}=event.data;if(!validateState(setup)||!setup.meta||setup.meta.demo||!keys||typeof keys!=='object'||Array.isArray(keys))throw Error('Invalid setup transfer.');
   const allowed=new Set(localProviders.map(p=>p.secret));
   if(Object.entries(keys).some(([key,value])=>!allowed.has(key)||typeof value!=='string'||value.length<8||value.length>8000||/[\r\n\x00]/.test(value)))throw Error('Invalid credential transfer.');
   await checkBridge();if(!bridgeReady)throw Error('Connect to the local app and try again.');
   for(const [secret,value] of Object.entries(keys))await localRequest('credentials',{secret,value});
   s=setup;const imported=await localRequest('workspace-create',{setup});workspaceReady=true;await refreshWorkspaceList();await activateWorkspace(imported.run,'gates');localStorage.setItem('basis-setup-migrated','true');reply('basis-setup-complete');note('Setup ready. Keys saved on this device.');
  }catch(error){reply('basis-setup-error');showMessage(error.message)}
 };
 window.addEventListener('message',receive);reply('basis-setup-ready');
 const readyTimer=setInterval(()=>reply('basis-setup-ready'),500);
 setTimeout(()=>{clearInterval(readyTimer);if(!processing)window.removeEventListener('message',receive)},15000);
}

let requirementService='',requirementSelected='';
function requirementCategory(g){return ['runtime','provider','organization'].includes(g.category)?g.category:({secret:'runtime',legal:'organization'}[g.id]||'provider')}
function requirementStatus(status){return {pass:'Verified',fail:'Failed',unverified:'Needs review'}[status]||'Needs review'}
function gates(requirementsOnly=false){const services=s.platforms.filter(p=>p.enabled);if(!services.some(p=>p.id===requirementService))requirementService=services[0]?.id||'';const selected=s.gates.find(g=>g.id===requirementSelected),review=selected?requirementReview(s,requirementService,selected.id):{};return (requirementsOnly?'':title('03 / TRUST','Services',''))+`${!requirementsOnly?serviceSelection()+(reviewEligible()?platformConfigurationFields():'')+workspaceChanges()+setupHandoff():`<div class="requirement-layout ${selected?'has-review':''}"><section class="requirement-list"><div class="results-section-heading"><h2>Requirements</h2><button class="inlinebtn" data-act="add-gate">${icon('plus',14)} Add requirement</button></div>${services.length?`<label class="requirement-service"><span class="sr-only">Requirement service</span><select id="requirement-service">${services.map(p=>`<option value="${esc(p.id)}" ${p.id===requirementService?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${[['runtime','Runtime'],['provider','Provider & account'],['organization','Organization']].map(([category,name])=>`<div class="requirement-group"><h3>${name}</h3>${s.gates.filter(g=>requirementCategory(g)===category).map(g=>{const r=requirementReview(s,requirementService,g.id);return `<button class="requirement-row ${g.id===requirementSelected?'selected':''}" data-requirement="${esc(g.id)}"><span><b>${esc(g.name)}</b><small>${g.required?'Mandatory':'Advisory'}</small></span><span class="requirement-state ${r.status}">${icon(r.status==='pass'?'check':r.status==='fail'?'cross':'clock',15)}${requirementStatus(r.status)}</span>${icon('chev',16)}</button>`}).join('')}</div>`).join('')}`:'<p class="muted">Select a service to review its requirements.</p>'}</section>${selected&&requirementService?`<aside class="requirement-editor"><header><div><h2>${esc(selected.name)}</h2><p>${esc(services.find(p=>p.id===requirementService)?.name)}</p></div><button class="iconbtn" data-close-requirement aria-label="Close requirement review">${icon('cross',20)}</button></header><form id="requirement-review"><label>Status<select name="status">${selectOptions([['unverified','Needs review'],['pass','Verified'],['fail','Failed']],review.status)}</select></label><label>Evidence<input name="url" type="url" maxlength="2000" value="${esc(review.url||'')}" placeholder="Document or account-setting link"></label><label>Notes<textarea name="notes" maxlength="8000" placeholder="What does this evidence confirm?">${esc(review.notes||'')}</textarea></label><div class="review-meta"><label>Reviewer<input name="reviewer" maxlength="200" value="${esc(review.reviewer||'')}" placeholder="Your name"></label><div><span>Reviewed</span><p>${review.reviewedAt?esc(new Date(review.reviewedAt).toLocaleDateString()):'Not reviewed'}</p></div></div><p class="results-help">${requirementCategory(selected)==='runtime'?'Review the actual runtime controls and their evidence.':'Verify the evidence against your account and requirements.'}</p><p id="requirement-feedback" role="alert"></p><footer><button type="button" class="inlinebtn" data-act="delete-gate" data-id="${esc(selected.id)}">Remove requirement</button><button type="button" class="secondary" data-close-requirement>Cancel</button><button type="submit" class="primary">Save review</button></footer></form></aside>`:''}</div>`}`}
function bindRequirements(){$('#requirement-service')?.addEventListener('change',e=>{requirementService=e.target.value;render()});document.querySelectorAll('[data-requirement]').forEach(b=>b.onclick=()=>{requirementSelected=b.dataset.requirement;render();$('#requirement-review select')?.focus()});document.querySelectorAll('[data-close-requirement]').forEach(b=>b.onclick=()=>{requirementSelected='';render()});const form=$('#requirement-review');if(form)form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));data.reviewedAt=new Date().toISOString();if(data.status!=='unverified'&&requirementReview({gateEvidence:{p:{g:data}}},'p','g').status==='unverified'){$('#requirement-feedback').textContent='Add an evidence link, notes, and reviewer before marking this verified or failed.';return}s.gateEvidence??={};s.gateEvidence[requirementService]??={};const previous=s.gateEvidence[requirementService][requirementSelected];data.history=[...(previous?.history||[]),...(previous?[Object.fromEntries(Object.entries(previous).filter(([k])=>k!=='history'))]:[])].slice(-50);s.gateEvidence[requirementService][requirementSelected]=data;s.gateResults[requirementService]??={};s.gateResults[requirementService][requirementSelected]=data.status;save();render();$('#requirement-feedback').textContent='Review saved.'}}
function editTask(task=null){addModal(task?'Edit task':'Define task',[
 {name:'name',label:'Task name'},{name:'type',label:'Work type',type:'select',options:TYPES.map(x=>[x,x])},
 {name:'difficulty',label:'Difficulty',type:'select',options:[['easy','Easy'],['medium','Medium'],['hard','Hard']]},
 {name:'acceptance',label:'Independent acceptance criteria'},
 {name:'sourcePath',label:'Source folder (absolute path; blank starts empty)',required:false},
 {name:'checksPath',label:'Independent checks folder (mounted read-only at /checks)',required:false},
 {name:'checkCommand',label:'Check command, e.g. python3 /checks/test_solution.py',required:false},
 {name:'baseline',label:'Baseline human minutes',type:'number',min:0,value:60}
 ].map(field=>({...field,value:task?.[field.name]??field.value})),values=>{const updated={...values,baseline:Number(values.baseline)};if(task)Object.assign(task,updated);else s.tasks.push({id:'T-'+Array.from(crypto.getRandomValues(new Uint32Array(4)),n=>n.toString(16).padStart(8,'0')).join(''),...updated})})}
function fairGuideButton(){return `<button class="secondary" data-act="fair-guide">${icon('book',16)} Fair testing guide</button>`;}
function pilot(){return title('01 / SET UP','Tasks & Benchmarks','Define the work each service will attempt and the criteria for accepting its result.',`<div class="inlineactions">${fairGuideButton()}<button class="primary" data-act="add-task">${icon('plus',16)} Add task</button></div>`)+`${s.tasks.length?'':'<div class="empty"><b>No tasks yet</b><p>Add a task with clear acceptance criteria and an estimate of human effort without the tool.</p></div>'}<div class="taskgrid">${s.tasks.map(t=>`<div class="panel task"><div class="smallcaps">${esc(t.id)} · ${esc(t.type)}</div><h3>${esc(t.name)}</h3><p>${esc(t.acceptance)}</p><p class="muted">${t.sourcePath?`Source: ${esc(t.sourcePath)}`:'Starts in an empty workspace'} · ${t.checkCommand?'Independent checks configured':'Human review required'}</p><div class="taskbottom"><span>${esc(t.difficulty)} · ${f(t.baseline)} min baseline</span><button class="secondary" data-act="edit-task" data-id="${esc(t.id)}">Edit task</button><button class="iconbtn" data-act="delete-task" data-id="${t.id}" title="Delete task">${icon('trash',16)}</button></div></div>`).join('')}</div><div class="results-section-heading"><h2>Benchmarks</h2></div>${benchmarkControls(runOptions())}${setupHandoff()}`;}
let packEntryOpen=false,liteState={status:'idle'},liteTimer=null,liteImportFeedback='';
const selectedPackDetails=new Map();
let evaluationHistory=[],evaluationSelected='',evaluationTimer=null,evaluationError='';
function runOptions(){const options=s.execution||{};return {platformReview:options.platformReview!==false,timeoutSeconds:Number.isInteger(options.timeoutSeconds)?options.timeoutSeconds:600,benchmarkPaths:Array.isArray(options.benchmarkPaths)?options.benchmarkPaths:[],integratedBenchmarks:Array.isArray(options.integratedBenchmarks)?options.integratedBenchmarks.filter(b=>b.id==='swebench-lite'):[],pendingLiteCount:options.pendingLiteCount||null}}
function currentEvaluation(){if(workspaceReady&&workspaceRun)return evaluationHistory.find(j=>j.id===workspaceRun.id)||null;return evaluationHistory.find(j=>j.id===evaluationSelected)||evaluationHistory[0]||null}
const consoleState=new Map();
function modelTaskStates(job,id){const active=['preparing','running'].includes(job.status);return (job.plan?.tasks||[]).map(task=>{const result=job.results.find(r=>candidateKey(r)===id&&r.taskIndex===task.index),current=active&&job.phase!=='prepare'&&(job.currentCandidate||job.currentAgent)===id&&job.currentTask===task.index;return {name:task.name,label:result?(result.checkPassed===false?'Checks failed':result.status):current?(job.phase==='check'?'Checking':'Running'):active?'Queued':'Not run',tone:result?(result.status==='completed'?(result.checkPassed===false?'is-warning':'is-ready'):result.status==='timeout'?'is-timeout':'is-warning'):current?'is-active':''}})}
function modelConsoleStatus(tasks){return tasks.find(t=>t.tone==='is-active')||tasks.find(t=>t.tone==='is-warning')||(tasks.length&&tasks.every(t=>t.label==='completed')?{label:'Completed',tone:'is-ready'}:tasks.find(t=>t.label==='Queued'||t.label==='Not run'))||{label:'Queued',tone:''}}
function completedRun(job){return job?.status==='partial'&&job.total>0&&job.results?.length===job.total&&job.results.every(r=>['completed','timeout'].includes(r.status))?{...job,status:'completed'}:job}
function runOutcomeSummary(job){const rows=job.results||[],parts=[],passed=rows.filter(r=>r.checkPassed===true).length,failed=rows.filter(r=>r.checkPassed===false).length,timed=rows.filter(r=>r.status==='timeout').length,errors=rows.filter(r=>!['completed','timeout'].includes(r.status)).length;if(passed)parts.push(`${passed} passed`);if(failed)parts.push(`${failed} failed checks`);if(timed)parts.push(`${timed} timed out`);if(errors)parts.push(`${errors} execution errors`);return parts.join(' · ')||'Run saved locally'}
function modelOutcomeBadges(job,id){const rows=(job.results||[]).filter(r=>candidateKey(r)===id),active=['preparing','running'].includes(job.status),counts=[['passed',rows.filter(r=>r.checkPassed===true).length,'good'],['failed',rows.filter(r=>r.checkPassed===false).length,'attention'],['timed out',rows.filter(r=>r.status==='timeout').length,'timeout'],['errors',rows.filter(r=>!['completed','timeout'].includes(r.status)).length,'attention']];return `<span class="model-outcome-counts">${counts.filter(([label,count])=>count||label==='passed').map(([label,count,tone])=>`<span class="model-outcome ${tone}">${icon(tone==='good'?'check':label==='timed out'?'clock':'cross',13)} ${count} ${label}</span>`).join('')}${active&&modelTaskStates(job,id).some(t=>t.tone==='is-active')?'<span class="model-outcome muted">In progress</span>':''}</span>`}
function runPhaseStates(job){
 job=completedRun(job);
 const active=['preparing','running'].includes(job.status),finished=['completed','partial'].includes(job.status),rows=job.results||[],phase=job.status==='preparing'||job.phase==='prepare'?0:job.phase==='check'?2:1;
 const prepared=finished||rows.length>0||job.phase==='agent'||job.phase==='check',agentsDone=finished||(active&&phase===2&&rows.length+1>=job.total),agentErrors=rows.some(r=>!['completed','timeout'].includes(r.status));
 const states=[prepared?'done':'pending',agentsDone?(agentErrors?'warning':'done'):'pending',finished?(agentErrors?'warning':'done'):'pending',finished?(job.status==='partial'?'warning':'done'):'pending'];
 if(active)states[phase]='current';else if(!finished)states[phase]='warning';
 return states;
}
function runProgress(job){
 job=completedRun(job);
 if(!job)return '<div class="run-idle"><h2>Your evaluation</h2><p>Run your selected tasks and benchmarks.</p></div>';
 const active=['preparing','running'].includes(job.status),phase=!active?3:job.status==='preparing'?0:job.phase==='check'?2:1;
 const heading=reviewEligible(job.plan?.setup||{})&&job.plan.platformReview!==false?'Coding tests':job.status==='preparing'?'Preparing your run':active?(phase===2?'Checking results':'Running your tasks'):({completed:'Evaluation complete',partial:'Evaluation needs review',failed:'Evaluation failed',stopped:'Evaluation stopped',interrupted:'Evaluation interrupted'}[job.status]||job.status);
 const elapsed=Math.max(0,Math.floor((job.finishedAt||Date.now()/1000)-job.startedAt)),time=`${Math.floor(elapsed/60).toString().padStart(2,'0')}:${(elapsed%60).toString().padStart(2,'0')}`;
 const streams=[{id:'setup',name:'Runner setup'},...(job.plan?.services||[]).map(p=>({id:candidateKey(p),name:candidateName(p)}))];
 return `<div class="run-heading"><span class="status-led ${active?'is-active':job.status==='completed'?'is-ready':'is-warning'}"></span><div><h2>${esc(heading)}</h2><p>${esc(active||['failed','stopped','interrupted'].includes(job.status)?job.message:'Review the outcomes and acceptance criteria in Results.')}</p></div><span class="pill">${esc(active?'In progress':job.status)}</span></div>
 <ol class="run-phases" aria-label="Evaluation progress">${runPhaseStates(job).map((state,i)=>{const name=['Prepare','Run tasks','Check results','Finish'][i],status={done:'Complete',current:'In progress',pending:'Pending',warning:'Needs attention'}[state];return `<li class="${state}" ${state==='current'?'aria-current="step"':''} aria-label="${name}: ${status}"><span aria-hidden="true">${state==='done'?'✓':state==='warning'?'!':i+1}</span>${name}</li>`}).join('')}</ol>
 <div class="run-meter"><div class="panelheading"><b>${job.results.length} of ${job.total} attempts finished</b><span class="muted">Elapsed ${time}</span></div><progress aria-label="Completed attempts" max="${job.total||1}" value="${job.results.length}"></progress><p class="muted">${active?(job.lastOutputAt?`Last output ${Math.max(0,Math.floor(Date.now()/1000-job.lastOutputAt))}s ago`:'Waiting for runner output…'):esc(runOutcomeSummary(job))}</p></div>

 <div class="run-consoles">${streams.map(stream=>{const key=job.id+':'+stream.id,state=consoleState.get(key)||{open:job.status==='failed'&&stream.id==='setup'||job.results.some(r=>candidateKey(r)===stream.id&&(r.status!=='completed'||r.checkPassed===false))},lines=(job.activity||[]).filter(e=>e.stream===stream.id),tasks=stream.id==='setup'?[]:modelTaskStates(job,stream.id),status=modelConsoleStatus(tasks);return `<details data-console="${esc(key)}" ${state.open?'open':''}><summary><span class="console-model-name">${esc(stream.name)}</span>${tasks.length?modelOutcomeBadges(job,stream.id):'<span class="muted">Activity</span>'}</summary>${tasks.length?`<div class="console-tasks">${tasks.map(t=>`<div><span>${esc(t.name)}</span><span class="run-state"><i class="status-led ${t.tone}"></i>${esc(t.label)}</span></div>`).join('')}</div>`:''}<div class="console-toolbar"><label><input type="checkbox" data-follow ${state.follow!==false?'checked':''}> Follow latest</label><button class="inlinebtn" data-copy-log>Copy</button><button class="inlinebtn" data-download-log>Download</button></div><pre tabindex="0" aria-label="${esc(stream.name)} output">${esc(lines.map(e=>new Date(e.time*1000).toLocaleTimeString()+'  '+e.text).join('\n')||(active?'Waiting for output…':'No output captured for this run.'))}</pre>${job.activityTruncated?'<small class="muted">Showing retained recent output.</small>':''}<span class="console-feedback" role="status"></span></details>`}).join('')}</div>
 <div class="run-footer"><span class="muted">${active?'You can leave this page; the local runner continues.':'Completed attempts are preserved.'}</span><div class="inlineactions">${active&&!workspaceReady?'<button class="secondary" id="stop-evaluation">Stop evaluation</button>':''}<button class="secondary" data-nav="results">View results ${icon('chev',16)}</button></div></div>`;
}
