function localRequired(){return `<section class="local-required" aria-labelledby="local-required-heading"><span class="local-required-icon" aria-hidden="true">${icon('play',28)}</span><h1 id="local-required-heading">Continue locally</h1><p>Run evaluations and view results in the local app.</p><button class="primary" data-act="continue-local">Continue locally ${icon('chev',16)}</button><button class="inlinebtn" data-act="connection-help">How to start locally</button><p id="handoff-feedback" role="status"></p></section>`;}
const benchmarkHelp={
 attemptTime:`<strong>Attempt time</strong><p>Elapsed time for agent execution and checks. Runner preparation is excluded.</p><p>For multiple tasks, this is the mean of recorded attempt durations, including failed attempts.</p>`,
 swebench:`<strong>SWE-bench Lite</strong><p>Fix real issues in public repositories, then grade patches with the official SWE-bench harness.</p><ul><li>Choose 1–300 tasks. Every model gets the same fixed selection.</li><li>Setup downloads and caches task images. Docker needs at least 8 GB memory and 20 GB free disk; larger selections need more.</li></ul><p class="help-note">Agents use the Basis coding environment; grading uses the pinned official environment. These are local evaluation results, not leaderboard submissions.</p>`,
 consent:`<strong>Provider consent</strong><p>This run sends task context and source files to the selected providers. Included platform research sends organization requirements and public-source excerpts to your judge. Both may incur API charges.</p><p class="help-note">Basis does not enforce a spending cap. Consent is required before starting.</p>`,
 execution:`<strong>Execution limits</strong><p>The time limit applies separately to each agent and independent check.</p><ul><li>One attempt per task and service, run sequentially.</li><li>Agents: 2 CPUs, 2 GB memory. SWE-bench grading: 2 CPUs, 4 GB.</li></ul><p class="help-note">Provider costs are not measured or capped. Your setup budget is context, not a spending limit.</p>`,
 humaneval:`<strong>HumanEval</strong><p>Ready-made Python coding exercises with automatic checks.</p><ul><li>Choose 1–50 tasks. Each selected service attempts the same tasks.</li><li>Basis uses a fixed subset of the original public exercises.</li></ul><p class="help-note">Results are from Basis’s runner, not an official leaderboard score.</p>`,
 pack:`<strong>Local benchmark pack</strong><p>A JSON file on this computer that lists tasks, starting files, and independent checks.</p><ul><li>Enter the full path to your <code>pack.json</code> file.</li><li>Each selected service attempts the same tasks.</li></ul><p class="help-note">This does not run official SWE-bench or Terminal-Bench harnesses. Import their existing reports from Results. See the README for the pack format.</p>`
};
function benchmarkHelpButton(kind,label){return `<button type="button" class="iconbtn context-help-button" data-context-help="${kind}" aria-label="About ${label}" aria-expanded="false">${icon('info',15)}</button>`;}
let activeHelp=null,helpSequence=0;
function closeContextHelp(){if(!activeHelp)return;clearTimeout(activeHelp.timer);activeHelp.button.setAttribute('aria-expanded','false');activeHelp.button.removeAttribute('aria-describedby');activeHelp.button.removeAttribute('aria-controls');activeHelp.popup.remove();activeHelp=null;}
function bindContextHelp(){document.querySelectorAll('[data-context-help]').forEach(button=>{
 const open=()=>{if(activeHelp?.button===button){clearTimeout(activeHelp.timer);return}closeContextHelp();const popup=document.createElement('div');popup.className='context-help-popup';popup.id=`context-help-${++helpSequence}`;popup.setAttribute('role','tooltip');popup.innerHTML=benchmarkHelp[button.dataset.contextHelp];document.body.append(popup);const state={button,popup,pinned:false,timer:null};activeHelp=state;
 state.position=()=>{const rect=button.getBoundingClientRect();if(rect.bottom<0||rect.top>innerHeight){closeContextHelp();return}popup.style.left=Math.max(12,Math.min(rect.left,innerWidth-popup.offsetWidth-12))+'px';popup.style.top=Math.max(12,rect.bottom+8+popup.offsetHeight>innerHeight?rect.top-popup.offsetHeight-8:rect.bottom+8)+'px'};
 button.setAttribute('aria-expanded','true');button.setAttribute('aria-describedby',popup.id);button.setAttribute('aria-controls',popup.id);popup.onpointerenter=()=>clearTimeout(state.timer);popup.onpointerleave=()=>scheduleClose();state.position();};
 const scheduleClose=()=>{if(activeHelp?.button===button&&!activeHelp.pinned&&document.activeElement!==button){clearTimeout(activeHelp.timer);activeHelp.timer=setTimeout(closeContextHelp,160)}};
 button.onpointerenter=e=>{if(e.pointerType!=='touch')open()};button.onpointerleave=scheduleClose;button.onfocus=open;button.onblur=()=>{if(activeHelp?.button===button)closeContextHelp()};button.onclick=()=>{if(activeHelp?.button===button&&activeHelp.pinned){closeContextHelp();return}open();activeHelp.pinned=true};
 });}
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&activeHelp){event.preventDefault();closeContextHelp()}});
