async function pollLite(){clearTimeout(liteTimer);if(!['pilot','record'].includes(page)||!bridgeReady||workspaceLocked())return;try{const owner=workspaceRun?.id;const {benchmark}=await localRequest('swebench-status',{});if(workspaceRun?.id!==owner)return;if(workspaceReady&&benchmark.workspaceId!==owner){if(['checking','downloading','preparing'].includes(benchmark.status)){liteState={status:'busy',message:'Preparing a benchmark in another run'};paintLite()}else if(liteState.status!=='idle'){liteState={status:'idle'};paintLite()}liteTimer=setTimeout(pollLite,2000);return}const changed=JSON.stringify(liteState)!==JSON.stringify(benchmark);liteState=benchmark;if(benchmark.status==='ready'&&runOptions().pendingLiteCount===benchmark.count){s.execution={...runOptions(),integratedBenchmarks:[{id:'swebench-lite',count:benchmark.count}],pendingLiteCount:null};save();paintLite()}else if(changed)paintLite()}catch(error){liteState={status:'error',message:error.message};paintLite()}if(['pilot','record'].includes(page))liteTimer=setTimeout(pollLite,2000)}
