function aggregateUsage(rows){return Object.fromEntries(['inputTokens','outputTokens','cacheReadTokens','cacheWriteTokens','estimatedCostUsd'].map(key=>{const measured=rows.map(r=>r.usage).filter(u=>u&&Number.isFinite(u[key]));return [key,{value:measured.length?measured.reduce((sum,u)=>sum+u[key],0):null,complete:measured.filter(u=>u[key==='estimatedCostUsd'?'costStatus':'tokenStatus']==='complete').length,total:rows.length}]}))}
