function recommendationRows(job,r){const excluded=r?.excludedSuites||excludedSuites(job.id),tasks=(r?.taskDefinitions||job.plan.tasks).filter(t=>!excluded.includes(t.suite)),ids=new Set(tasks.map(t=>t.index));return job.plan.services.map(p=>{const source=r?.measurementSnapshot?.map(a=>({...a.measurements,taskIndex:a.taskIndex,candidateId:candidateKey(job.plan.services.find(p=>p.id===r.candidateMap[a.candidate].service&&p.model===r.candidateMap[a.candidate].model)||{})}))||job.results;const attempts=source.filter(a=>candidateKey(a)===candidateKey(p)&&ids.has(a.taskIndex)),times=attempts.map(a=>a.durationSeconds).filter(Number.isFinite),alias=Object.entries(r?.candidateMap||{}).find(([,v])=>v.service===p.id&&v.model===p.model)?.[0],judgment=r?.report?.candidates.find(c=>c.candidate===alias)||r?.quality?.candidates.find(c=>c.candidate===alias);return {p,alias,judgment,total:tasks.length,graded:attempts.filter(a=>typeof a.checkPassed==='boolean').length,passed:attempts.filter(a=>a.checkPassed===true).length,time:times.length?times.reduce((a,b)=>a+b,0)/times.length:null,usage:aggregateUsage(attempts)}})}
