function recommendationFindings(items,r,job){return `<ul class="rec-findings">${(items||[]).map(v=>`<li><span>${esc(recommendationText(v.text,r,job))}</span><div>${recommendationEvidence(v.evidence,r)}</div></li>`).join('')}</ul>`}
let recEvidenceTab='sources',recEvidenceOpen=true,recClock=null;const recRendered=new Map(),recDetailState=new Map();
const recTime=seconds=>{const n=Math.max(0,Math.floor(seconds||0));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`};
function recommendationActivity(r,data,job){
 const calls=(data.judgeRuns||job.judgeRuns||[]).filter(c=>c.generationId===r.id),quality=calls.filter(c=>c.stage==='quality').at(-1),final=calls.find(c=>c.stage==='recommendation'),active=recommendationActive(r),events=[];
 if(r.evidencePreparedAt||quality?.startedAt)events.push([r.evidencePreparedAt||quality.startedAt,'Evidence prepared','done']);
 if(r.status==='comparing'&&r.taskCount)events.push([quality?.startedAt||r.evidencePreparedAt,`Reviewing task ${r.currentTask||1} of ${r.taskCount} · ${r.completedTasks||0} complete`,'active']);
 else if(quality?.status==='completed')events.push([quality.finishedAt,'Model comparison completed','done']);
 else if(quality)events.push([quality.finishedAt||quality.startedAt,quality.status==='running'?'Comparing models':'Model comparison '+quality.status,quality.status==='running'?'active':'attention']);
 if(final)events.push([final.finishedAt||final.startedAt,final.status==='completed'?'Recommendation received':final.status==='running'?'Writing final recommendation':'Recommendation '+final.status,final.status==='running'?'active':final.status==='completed'?'done':'attention']);
 if(!events.length)events.push([r.startedAt,'Preparing evidence',active?'active':'attention']);
 if(r.status==='stopping')events.push([null,'Stop requested · waiting for provider','attention']);
 return `<div class="rec-live-band"><div><h3>Activity</h3><ol class="rec-activity">${events.map(([time,label,state])=>`<li class="${state}"><span class="rec-event-icon">${state==='done'?icon('check',12):'<i></i>'}</span><time>${time?recTime(time-r.startedAt):'—'}</time><span>${esc(label)}</span></li>`).join('')}</ol>${active?'<div class="rec-indeterminate" aria-label="Judge request in progress"></div>':''}</div>${active?'<div class="rec-live-preview"><h3>Final recommendation</h3><div class="rec-skeleton" aria-hidden="true"></div><div class="rec-skeleton short" aria-hidden="true"></div></div>':''}</div>${r.quality?`<details class="rec-details rec-quality"><summary>Completed assessment <small>${r.quality.candidates.length} models</small></summary>${r.quality.candidates.map(c=>`<section><h3>${esc(recommendationText(c.candidate,r,job))}</h3><p>${esc(c.assessment)}</p>${recommendationFindings(c.strengths,r,job)}${recommendationFindings(c.weaknesses,r,job)}</section>`).join('')}</details>`:''}`;
}
function recommendationSources(r,data,job){
 const coverage=r.evidenceSummary,u=data.usage,limitations=[...new Set([...(r.quality?.limitations||[]),...(r.report?.limitations||[])])];
 const metric=(ic,label,value,action='',attention=false)=>`<div class="rec-source-item">${icon(ic,17)}<div><span>${label}</span><b class="${attention?'attention':''}">${value}</b></div>${action}</div>`;
 return `<details class="rec-evidence" id="rec-evidence" ${recEvidenceOpen?'open':''}><summary>${icon('book',16)} Evidence <small>${r.taskCount||'—'} tasks · ${job.plan.services.length} models</small></summary><div class="rec-evidence-tabs" role="tablist" aria-label="Evidence details">${['sources','method','usage'].map(tab=>`<button id="rec-tab-${tab}" role="tab" aria-controls="rec-panel-${tab}" aria-selected="${recEvidenceTab===tab}" tabindex="${recEvidenceTab===tab?0:-1}" data-rec-tab="${tab}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div>
 <div id="rec-panel-sources" role="tabpanel" aria-labelledby="rec-tab-sources" ${recEvidenceTab==='sources'?'':'hidden'}><div class="rec-source-grid">${metric('code','Source files',coverage?`${coverage.filesIncluded} included${coverage.filesOmitted?' · '+coverage.filesOmitted+' omitted':''}`:'Not recorded','<button class="inlinebtn" data-rec-files>View files '+icon('chev',13)+'</button>')}${metric('check','Independent checks',coverage?`${coverage.checksRecorded} / ${coverage.attempts} recorded`:'Not recorded')}${metric('users','Human reviews',coverage?`${coverage.humanReviewed} / ${coverage.attempts} reviewed`:'Not recorded','',coverage&&coverage.humanReviewed<coverage.attempts)}${metric('shield','Requirements',coverage?(coverage.requirementsTotal?`${coverage.requirementsPending} need review`:'None recorded'):'Not recorded','',!coverage||coverage.requirementsPending>0||!coverage.requirementsTotal)}</div></div>
 <div id="rec-panel-method" role="tabpanel" aria-labelledby="rec-tab-method" ${recEvidenceTab==='method'?'':'hidden'}><dl class="rec-method"><dt>Code assessment</dt><dd>Identity withheld · randomized order</dd><dt>Recommendation</dt><dd>Saved priorities, workload, measurements and reviews</dd><dt>Required controls</dt><dd>Documentary reviews; never certified by coding tests</dd><dt>Rubric</dt><dd>${esc(r.promptVersion)}</dd><dt>Excluded suites</dt><dd>${esc(r.excludedSuites?.join(', ')||'None')}</dd></dl>${limitations.length?`<details class="rec-limitations"><summary>Limitations <small>${limitations.length}</small></summary><ul>${limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}<p class="rec-method-note">Judge findings need human review. Blinding reduces some bias; it does not prove independence.</p></div>
 <div id="rec-panel-usage" role="tabpanel" aria-labelledby="rec-tab-usage" ${recEvidenceTab==='usage'?'':'hidden'}><div class="rec-usage-head"><span>Judge calls · all generations</span><b>${usageMetric(u?.estimatedCostUsd,true)} <small>estimated</small></b></div><dl class="rec-token-grid">${[['inputTokens','Input · uncached'],['outputTokens','Output'],['cacheReadTokens','Cache read'],['cacheWriteTokens','Cache write']].map(([key,label])=>`<div><dt>${label}</dt><dd>${usageMetric(u?.[key])}</dd></div>`).join('')}</dl><div class="table-scroll"><table class="rec-call-table"><thead><tr><th>Call</th><th>Status</th><th>Duration</th><th>Est. cost</th></tr></thead><tbody>${(data.judgeRuns||job.judgeRuns||[]).map(c=>`<tr><td>${c.stage==='quality'?(c.taskIndex==null?'Comparison':`Task ${c.taskIndex+1}`):'Recommendation'}</td><td>${esc(c.status)}</td><td>${c.finishedAt?recTime(c.finishedAt-c.startedAt):'In progress'}</td><td>${c.usage?.estimatedCostUsd==null?'Not recorded':usageMoney(c.usage.estimatedCostUsd)}</td></tr>`).join('')}</tbody></table></div><p class="rec-method-note">Includes failed calls. List-price estimates may differ from your bill; unreported usage stays unknown.</p></div>
 <div class="rec-snapshot"><span>${icon(r.evidenceDigest?'check':'clock',13)} ${r.evidenceDigest?'Snapshot saved':'Preparing snapshot'}</span>${r.evidenceDigest?`<button class="inlinebtn" id="rec-copy-snapshot" title="Copy full evidence digest" aria-label="Copy evidence digest">${icon('copy',13)} <code>${esc(r.evidenceDigest.slice(0,6))}…${esc(r.evidenceDigest.slice(-4))}</code></button>`:''}</div></details>`;
}

function recommendationCanvas(job){const data=recommendationValue(job);recRendered.set(job.id,JSON.stringify(data));const r=data.recommendation,active=recommendationActive(r),report=r?.status==='completed'?r.report:null,stale=r?.stale,rows=recommendationRows(job,r),error=data.error||r?.error,elapsed=r?Math.max(0,Math.floor((r.finishedAt||Date.now()/1000)-r.startedAt)):0,stage=r?.status==='preparing'?0:r?.status==='comparing'?1:r?.quality?2:1;
 const label=active?({preparing:'Preparing evidence',comparing:r.taskCount?`Reviewing task ${r.currentTask||1} of ${r.taskCount}`:'Comparing models',writing:'Writing recommendation',stopping:'Stopping after current request'}[r.status]):stale?'Evidence changed':r?.status==='completed'?'Complete':r?.status==='failed'?'Generation failed':r?.status==='stopped'?'Stopped':r?.status==='interrupted'?'Interrupted':'Ready to generate';
 return `${platformRecommendation(job)}<div class="rec-toolbar"><div role="status"><span class="rec-dot ${active?'active':report?'complete':''}"></span><span>${label}</span>${r?`<small id="rec-elapsed" aria-label="${active?'Elapsed':'Duration'}">${recTime(elapsed)}</small>`:''}</div><div class="rec-toolbar-actions">${r?'':'<button class="inlinebtn" data-rec-settings>Configure judge</button>'}<button class="${active?'secondary':'primary'}" id="${active?'stop-recommendation':'generate-recommendation'}" ${recommendationBusy||r?.status==='stopping'?'disabled':''}>${icon(active?'stop':'spark',15)} ${active?'Stop':r?.status==='failed'||r?.status==='interrupted'?'Retry recommendation':report?'Regenerate recommendation':'Generate recommendation'}</button></div></div>
 ${!r?'<p class="rec-consent">Generate uses judge API credits and shares this run’s code and evidence.</p>':''}
 ${error?`<div class="rec-notice" role="alert">${esc(error)}</div>`:''}
 ${stale?'<div class="rec-notice" role="status">Evidence or selected suites changed. This assessment is out of date; regenerate before using it.</div>':''}
 <section class="rec-canvas ${stale?'rec-stale':''}" aria-label="Recommendation report" aria-busy="${!!active}">
 ${active?`<ol class="rec-stages" aria-label="Judge progress">${['Evidence','Comparison','Recommendation'].map((name,i)=>`<li class="${i<stage?'done':i===stage?'current':''}" ${i===stage?'aria-current="step"':''}><span>${i<stage?icon('check',12):''}</span>${name}</li>`).join('')}</ol>`:''}
 ${!r||report?`<header class="rec-heading"><div><span class="smallcaps">${report?'RECOMMENDATION':active?'JUDGE ASSESSMENT':'RECOMMENDATION'}</span><h2>${report?esc(recommendationText(report.headline,r,job)):active?`Comparing ${rows.length} models`:'Turn your results into a recommendation'}</h2><p>${report?esc(recommendationText(report.summary,r,job)):active?'Quality, cost, reliability, and team fit.':'Generate a comparison grounded in this run and your team’s priorities.'}</p></div>${report?`<span class="pill">${stale?'Out of date':report.outcome==='more_evidence'?'Limited evidence':report.outcome==='tie'?'No clear winner':r.readiness?.blocking?.length?'Conditional preference':'Technical preference'}</span>`:''}</header>`:''}
 ${active||r?`<div class="table-scroll rec-comparison"><table><caption class="sr-only">${report?'Model comparison':'Recorded run evidence'}</caption><thead><tr><th>Model</th><th>Checks passed</th><th>Avg. attempt time</th><th>Est. API cost</th>${report?'<th>Judge assessment</th>':''}</tr></thead><tbody>${rows.map(row=>`<tr class="${!stale&&report?.preferredCandidate===row.alias?'rec-preferred':''}"><td><b>${esc(displayModel(row.p))}</b><small>${esc(row.p.name)} ${!stale&&report?.preferredCandidate===row.alias?'<span class="rec-preferred-label">Preferred</span>':''}</small></td><td><span class="rec-checks">${row.graded===row.total&&row.passed===row.total?icon('check',14):''}${row.graded?`${row.passed} / ${row.total}`:'Not checked'}</span>${row.graded<row.total?`<small>${row.graded} checked</small>`:''}</td><td>${row.time===null?'Not recorded':f(row.time,1)+' s'}</td><td title="${esc(usageTokenCell(row.usage).replace(/<[^>]*>/g,' '))}">${usageMetric(row.usage.estimatedCostUsd,true)}</td>${report?`<td>${esc(recommendationText(row.judgment?.assessment||'Not assessed',r,job))}</td>`:''}</tr>`).join('')}</tbody></table></div>`:''}
 ${report?`<div class="rec-takeaways"><div><h3>Why this choice</h3>${recommendationFindings(report.reasons.slice(0,3),r,job)}</div><div><h3>Before rollout</h3><p class="rec-readiness">${icon('shield',16)} ${r.readiness?.blocking?.length?`${r.readiness.blocking.length} mandatory requirement reviews unresolved`:r.readiness?.requiredCount?'Saved requirements reviewed':'No mandatory requirements recorded'}</p>${reviewEligible(job.plan.setup)?'':`<button class="inlinebtn" data-rec-requirements>Review requirements ${icon('chev',14)}</button>`}</div></div><details class="rec-details"><summary>Detailed comparison <small>Quality · Reliability · Cost · Team fit</small></summary>${r.quality?.candidates.map(c=>`<section><h3>${esc(recommendationText(c.candidate,r,job))}</h3><p>${esc(c.assessment)}</p>${recommendationFindings(c.strengths,r,job)}${recommendationFindings(c.weaknesses,r,job)}</section>`).join('')||''}<h3>Tradeoffs</h3>${recommendationFindings(report.tradeoffs,r,job)}<h3>Next steps</h3><ul>${report.nextSteps.map(t=>`<li>${esc(recommendationText(t,r,job))}</li>`).join('')}</ul></details>`:r?recommendationActivity(r,data,job):''}

 ${report?`<footer class="rec-footer"><span></span>${report?'<div><button class="inlinebtn" id="copy-recommendation">'+icon('copy',14)+' Copy</button><button class="inlinebtn" id="export-recommendation">'+icon('download',14)+' Export</button></div>':''}</footer>`:''}</section>${r?recommendationSources(r,data,job):''}<div id="rec-feedback" role="status"></div>`;
}
function recommendationMarkdown(job){const data=recommendationValue(job),r=data.recommendation,report=r.report,text=v=>recommendationText(v,r,job),findings=items=>items.map(v=>`- ${text(v.text)}\n  Evidence: ${v.evidence.join(', ')}`).join('\n');return `# ${text(report.headline)}\n\n${text(report.summary)}\n\n${r.stale?'OUT OF DATE — evidence changed.\n\n':''}## Model comparison\n\n| Model | Checks | Avg. time | Estimated API cost | Assessment |\n|---|---|---|---|---|\n${recommendationRows(job,r).map(v=>`| ${displayModel(v.p)} | ${v.passed}/${v.total} | ${v.time==null?'Unknown':f(v.time,1)+' s'} | ${usageMetric(v.usage.estimatedCostUsd,true)} | ${text(v.judgment?.assessment).replace(/\|/g,'/')} |`).join('\n')}\n\n## Why this choice\n${findings(report.reasons)}\n\n## Tradeoffs\n${findings(report.tradeoffs)}\n\n## Next steps\n${report.nextSteps.map(v=>'- '+text(v)).join('\n')}\n\n## Limitations\n${[...(r.quality?.limitations||[]),...report.limitations].map(v=>'- '+v).join('\n')}\n\n## Readiness\n${r.readiness.note}\n${r.readiness.blocking.map(v=>'- '+v.name+': '+v.status).join('\n')}\n\n## Audit\nJudge: ${r.provider} / ${r.model}\nRubric: ${r.promptVersion}\nEvidence: ${r.evidenceDigest}\nGenerated: ${new Date(r.finishedAt*1000).toISOString()}\nJudge estimated cost (all calls): ${usageMetric(data.usage?.estimatedCostUsd,true)}\n`}
function bindRecommendation(){
 clearInterval(recClock);
 const activeJob=currentEvaluation(),activeRec=activeJob&&recommendationValue(activeJob).recommendation;
 document.querySelectorAll('#recommendation-host details').forEach(d=>{const key=activeJob?.id+':'+(d.id||d.querySelector('summary')?.textContent);if(recDetailState.has(key))d.open=recDetailState.get(key);d.ontoggle=()=>{if(d.isConnected)recDetailState.set(key,d.open)}});
 if(page==='results'&&resultsTab==='recommendation'&&recommendationActive(activeRec))recClock=setInterval(()=>{if(page!=='results'||resultsTab!=='recommendation'){clearInterval(recClock);return}const clock=$('#rec-elapsed');if(clock)clock.textContent=recTime(Date.now()/1000-activeRec.startedAt)},1000);
 document.querySelectorAll('[data-rec-tab]').forEach((button,i,buttons)=>{button.onclick=()=>{recEvidenceTab=button.dataset.recTab;buttons.forEach(b=>{const on=b===button;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;$('#rec-panel-'+b.dataset.recTab).hidden=!on})};button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:-1)+3)%3;buttons[n].click();buttons[n].focus()}});
 $('#rec-evidence')?.addEventListener('toggle',e=>{recEvidenceOpen=e.target.open});
 document.querySelectorAll('[data-rec-files]').forEach(b=>b.onclick=()=>openArtifacts(currentEvaluation().id,null,b));
 $('#rec-copy-snapshot')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(recommendationValue(currentEvaluation()).recommendation.evidenceDigest);$('#rec-feedback').textContent='Evidence digest copied'}catch{$('#rec-feedback').textContent='Copy unavailable.'}});

 document.querySelectorAll('[data-result-tab]').forEach((button,i,buttons)=>{button.onclick=()=>{resultsTab=button.dataset.resultTab;render();document.querySelector(`[data-result-tab="${resultsTab}"]`)?.focus()};button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length].click()}});
 document.querySelectorAll('[data-rec-settings]').forEach(b=>b.onclick=()=>{page='settings';render()});
 document.querySelectorAll('[data-rec-requirements]').forEach(b=>b.onclick=()=>{resultsTab='results';setupTab='requirements';render();document.querySelector('.saved-setup')?.scrollIntoView({behavior:'smooth'})});
 document.querySelectorAll('[data-rec-evidence]').forEach(b=>b.onclick=()=>{const job=currentEvaluation(),r=recommendationValue(job).recommendation,ref=r.references[b.dataset.recEvidence];if(ref.kind==='artifact'||ref.kind==='attempt'){const p=job.plan.services.find(p=>p.id===r.candidateMap[ref.candidate]?.service&&p.model===r.candidateMap[ref.candidate]?.model);if(p)openArtifacts(job.id,`${ref.taskIndex}:${candidateKey(p)}`,b)}else if(ref.kind==='platform'){resultsTab='organization';fitSelected={config:ref.configuration,requirement:ref.requirement};render()}else{resultsTab='results';if(ref.kind==='requirement')setupTab='requirements';render()}});
 $('#generate-recommendation')?.addEventListener('click',async()=>{const job=currentEvaluation();recommendationBusy=true;$('#generate-recommendation').disabled=true;try{const value=await localRequest('recommendation-start',{id:job.id,excludedSuites:excludedSuites(job.id),consent:true});recommendationCache.set(job.id,value)}catch(error){recommendationCache.set(job.id,{...recommendationValue(job),error:error.message})}finally{recommendationBusy=false;if(page==='results'&&currentEvaluation()?.id===job.id)render()}});
 $('#stop-recommendation')?.addEventListener('click',async()=>{const job=currentEvaluation();$('#stop-recommendation').disabled=true;try{const value=await localRequest('recommendation-stop',{id:job.id});recommendationCache.set(job.id,{...recommendationValue(job),...value});if(page==='results'&&currentEvaluation()?.id===job.id)render()}catch(error){if($('#rec-feedback'))$('#rec-feedback').textContent=error.message}});
 $('#copy-recommendation')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(recommendationMarkdown(currentEvaluation()));$('#rec-feedback').textContent='Copied'}catch{$('#rec-feedback').textContent='Copy unavailable. Export the report instead.'}});
 $('#export-recommendation')?.addEventListener('click',()=>downloadFile(recommendationMarkdown(currentEvaluation()),'basis-recommendation.md','text/markdown'));
}
async function pollRecommendation(){clearTimeout(recommendationTimer);if(page!=='results'||resultsTab!=='recommendation'||!bridgeReady)return;const job=currentEvaluation();if(!job)return;try{const data=await localRequest('recommendation-status',{id:job.id,excludedSuites:excludedSuites(job.id)});if(page!=='results'||currentEvaluation()?.id!==job.id||resultsTab!=='recommendation')return;const previous=recommendationValue(job);recommendationCache.set(job.id,data);if(recRendered.get(job.id)!==JSON.stringify(data)){const host=$('#recommendation-host');if(host&&!window.getSelection()?.toString()){const focusId=host.contains(document.activeElement)?document.activeElement.id:null;const detailKey=d=>d.id||d.querySelector('summary')?.textContent;const opened=new Map([...host.querySelectorAll('details')].map(d=>[detailKey(d),d.open]));host.innerHTML=recommendationCanvas(job);host.querySelectorAll('details').forEach(d=>{if(opened.has(detailKey(d)))d.open=opened.get(detailKey(d))});bindRecommendation();if(focusId)document.getElementById(focusId)?.focus()}}}catch(error){if($('#rec-feedback'))$('#rec-feedback').textContent='Connection lost. '+error.message}recommendationTimer=setTimeout(pollRecommendation,2000)}

function results(){const job=currentEvaluation();if(!job)return title('03 / RESULTS','Evaluation results','')+`<div id="results-feedback" role="status">${esc(evaluationError)}</div><section class="empty-results"><h2>No evaluations yet</h2><p>Run an evaluation to see results here.</p><button class="primary" data-nav="record">Run evaluation</button></section>`;
 if(resultsTab==='organization'&&!reviewEligible(job.plan.setup))resultsTab='results';
 const excluded=excludedSuites(job.id),suites=[...new Set(job.plan.tasks.map(t=>t.suite))],visible=suites.filter(suite=>!excluded.includes(suite));if(resultsSuite!=='all'&&!visible.includes(resultsSuite))resultsSuite='all';const shown=visible.filter(suite=>resultsSuite==='all'||resultsSuite===suite),rows=job.results.filter(r=>shown.includes(r.suite)),tasks=job.plan.tasks.filter(t=>shown.includes(t.suite));
 return `<div class="results-page"><header class="results-header"><div><span class="smallcaps">03 / RESULTS</span><h1>Evaluation results</h1></div><div class="results-header-actions" ${resultsTab!=='results'?'hidden':''}><span class="result-status ${job.status==='completed'?'good':job.status==='partial'||job.status==='failed'?'attention':''}">${icon(job.status==='completed'?'check':'clock',16)}<span class="capitalize">${esc(job.status)}</span></span><button class="secondary" id="export-evaluation">${icon('download',16)} Export</button></div><label class="results-run-selector" ${workspaceReady?'hidden':''}><span class="sr-only">Evaluation</span><select id="evaluation-history">${evaluationHistory.map(j=>`<option value="${esc(j.id)}" ${j.id===job.id?'selected':''}>${esc(j.plan?.setup?.meta?.name||j.plan?.tasks?.[0]?.name||'Evaluation')} · ${esc(new Date(j.startedAt*1000).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))}</option>`).join('')}</select></label><span class="results-run-meta" ${resultsTab!=='results'?'hidden':''}>${job.plan.services.length} models · ${job.plan.tasks.length} ${job.plan.tasks.length===1?'task':'tasks'} · ${job.results.length} / ${job.total} attempts finished</span></header>
<div id="results-feedback" role="status">${esc(evaluationError)}</div>${['failed','interrupted','stopped','partial'].includes(job.status)?`<p class="results-run-notice">${esc(job.message)}</p>`:''}
${recommendationTabs()}<div id="result-view" role="tabpanel" aria-labelledby="result-tab-${resultsTab}">${resultsTab==='organization'?fitMatrix(job):resultsTab==='recommendation'?`<div id="recommendation-host">${recommendationCanvas(job)}</div>`:`${usageOverview(job)}<section class="model-comparison"><div class="results-section-heading"><h2>Model comparison</h2><label><span class="sr-only">Result suite</span><select id="results-suite"><option value="all">${visible.length===1?esc(visible[0]):'All suites'}</option>${visible.length>1?visible.map(suite=>`<option ${resultsSuite===suite?'selected':''} value="${esc(suite)}">${esc(suite)}</option>`).join(''):''}</select></label></div>${(job.plan.benchmarks||[]).length?`<details class="results-benchmark-filter"><summary>Benchmark evidence</summary>${job.plan.benchmarks.map(b=>`<label><input type="checkbox" data-include-suite="${esc(b.name)}" ${excluded.includes(b.name)?'':'checked'}>${esc(b.name)}</label>`).join('')}</details>`:''}
${shown.map(suite=>`<div class="suite-comparison">${shown.length>1?`<h3>${esc(suite)}</h3>`:''}<div class="table-scroll"><table><thead><tr><th>Model</th><th>Checks</th><th>Attempt time ${benchmarkHelpButton('attemptTime','attempt time')}</th><th>Est. API cost</th><th>Tokens</th><th>Errors</th><th>Review</th></tr></thead><tbody>${job.plan.services.map(p=>{const attempts=rows.filter(r=>r.suite===suite&&candidateKey(r)===candidateKey(p)),total=tasks.filter(t=>t.suite===suite).length,passed=attempts.filter(r=>r.checkPassed===true).length,graded=attempts.filter(r=>typeof r.checkPassed==='boolean').length,durations=attempts.map(r=>r.durationSeconds).filter(v=>Number.isFinite(v)),reviews=attempts.map(r=>job.reviews?.[attemptKey(r)]).filter(Boolean),rejected=reviews.some(r=>!r.accepted),allReviewed=reviews.length===total,usage=aggregateUsage(attempts);return `<tr><td title="${esc(p.model)}"><b>${esc(displayModel(p))}</b><small>${esc(p.name)}</small></td><td><span class="result-status ${graded===total&&passed===total?'good':graded>passed?'attention':''}">${graded===total&&passed===total?icon('check',16):''}${graded?`${passed} / ${total} passed`:'Not checked'}</span>${graded<total?`<small>${graded} / ${total} checked</small>`:''}</td><td>${durations.length?`${f(durations.reduce((a,b)=>a+b,0)/durations.length,1)} s${total>1?'<small>average</small>':''}`:'—'}</td><td>${usageMetric(usage.estimatedCostUsd,true)}</td><td>${usageTokenCell(usage)}</td><td>${attempts.filter(r=>r.status!=='completed').length}</td><td>${reviewBadge(rejected?{accepted:false}:allReviewed?{accepted:true}:null)}${reviews.length&&!allReviewed?`<small>${reviews.length} / ${total} reviewed</small>`:''}</td></tr>`}).join('')}</tbody></table></div></div>`).join('')||'<p class="results-help">No suites selected.</p>'}</section>
<section class="task-results"><h2>Task results</h2>${tasks.map(task=>`<section class="task-result-group"><div class="results-section-heading"><h3>${esc(task.name)}</h3><span>${esc(task.suite)}</span></div><details class="shared-criteria"><summary>Acceptance criteria</summary><div>${criteriaMarkup(task.acceptance)}</div></details><div class="result-model-grid">${job.plan.services.map(p=>{const r=rows.find(r=>r.taskIndex===task.index&&candidateKey(r)===candidateKey(p)),review=r?job.reviews?.[attemptKey(r)]:null;return `<article class="attempt-row result-model-card"><h3 title="${esc(p.model)}">${esc(displayModel(p))}</h3><p class="result-provider">${esc(p.name)}</p><div class="result-model-status">${resultCheck(r)}${reviewBadge(review)}</div><div class="result-card-actions"><button class="primary" data-review-attempt="${r?esc(attemptKey(r)):''}" ${r?'':'disabled'}>${review?'Edit review':'Review result'}</button><button class="inlinebtn" data-artifacts="${r?esc(attemptKey(r)):''}" ${r?'':'disabled'}>Artifacts ${icon('chev',15)}</button></div>${review?`<div class="review-note"><span>${review.accepted?'Human accepted':'Human rejected'}</span><p>${esc(review.notes)}</p></div>`:''}<details class="technical-details"><summary>Technical details</summary><dl><dt>Model ID</dt><dd><code>${esc(p.model)}</code></dd><dt>Status</dt><dd>${esc(r?.status||'Not run')}</dd><dt>Duration</dt><dd>${Number.isFinite(r?.durationSeconds)?f(r.durationSeconds,1)+' s':'Not recorded'}</dd><dt>Check</dt><dd><code>${esc(task.grader==='swebench-lite'?'Official SWE-bench '+task.harness:task.checkCommand||'Not configured')}</code></dd><dt>Agent exit</dt><dd>${esc(r?.agentExitCode??'Not recorded')}</dd><dt>Check exit</dt><dd>${esc(r?.checkExitCode??'Not run')}</dd><dt>Est. API cost</dt><dd>${r?.usage?.estimatedCostUsd!=null?usageMoney(r.usage.estimatedCostUsd)+(r.usage.costStatus==='partial'?' · partial':''):'Not recorded'}</dd>${usageDetails(r)}${review?.usageCost!=null?`<dt>Reported cost</dt><dd>${usageMoney(review.usageCost)} · manual</dd>`:''}<dt>Human effort</dt><dd>${(review?.humanMinutes??r?.humanMinutes)!=null?f(review?.humanMinutes??r?.humanMinutes)+' min':'Not recorded'}</dd>${task.revision?`<dt>Dataset revision</dt><dd><code>${esc(task.revision)}</code></dd>`:''}</dl>${r?.error?`<p>${esc(r.error)}</p>`:''}${r?.gradingReason?`<p>${esc(r.gradingReason)}</p>`:''}</details></article>`}).join('')}</div></section>`).join('')}</section>${workspaceReady?`<details class="workspace-saved-setup"><summary>${icon('folder',16)} Saved setup</summary>${savedSetup(job)}</details>`:savedSetup(job)}<footer class="results-local-footer"><span>${icon('folder',18)} Saved locally</span><button class="inlinebtn" data-artifacts="">View files ${icon('chev',16)}</button></footer>`}</div></div>`;
}
function downloadFile(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
