function highlightArtifact(name,source){
 const ext=name.split('.').pop().toLowerCase(),python=ext==='py',shell=['sh','bash','zsh','yaml','yml','toml'].includes(ext),json=ext==='json',js=['js','jsx','ts','tsx','mjs','cjs'].includes(ext);
 if(!python&&!shell&&!json&&!js)return esc(source);
 // Tokenize the original text, then escape every token before adding presentation markup.
 const strings=python?`(?:"""[\\s\\S]*?(?:"""|$)|'''[\\s\\S]*?(?:'''|$)|"(?:\\\\.|[^"\\\\\\n])*"|'(?:\\\\.|[^'\\\\\\n])*')`:`(?:"(?:\\\\.|[^"\\\\\\n])*"|'(?:\\\\.|[^'\\\\\\n])*'|\x60(?:\\\\.|[^\x60\\\\])*\x60)`;
 const comments=python||shell?'#[^\\n]*':js?'//[^\\n]*|/\\*[\\s\\S]*?(?:\\*/|$)':'(?!)';
 const tokens=new RegExp(`${strings}|${comments}|\\b(?:0x[\\da-fA-F]+|\\d+(?:\\.\\d+)?(?:[eE][+-]?\\d+)?)\\b|\\b[A-Za-z_$][\\w$]*\\b`,'g');
 const keywords=new Set((python?'and as assert async await break class continue def del elif else except finally for from global if import in is lambda nonlocal not or pass raise return try while with yield':js?'as async await break case catch class const continue debugger default delete do else export extends finally for from function if import in instanceof let new of return static super switch throw try typeof var void while yield':'if then else elif fi for in do done case esac function export').split(' '));
 let output='',cursor=0;
 for(const match of source.matchAll(tokens)){
  const value=match[0],start=match.index;output+=esc(source.slice(cursor,start));cursor=start+value.length;
  const kind=/^(?:#|\/\/|\/\*)/.test(value)?'comment':/^["'`]/.test(value)?json&&/^\s*:/.test(source.slice(cursor))?'key':'string':/^\d/.test(value)?'number':/^(True|False|None|true|false|null|undefined)$/.test(value)?'literal':keywords.has(value)&&!json?'keyword':!json&&/^\s*\(/.test(source.slice(cursor))?'function':'';
  output+=kind?`<span class="syntax-${kind}">${esc(value)}</span>`:esc(value);
 }
 return output+esc(source.slice(cursor));
}

async function openArtifacts(id,key,opener){const dialog=document.createElement('dialog');dialog.className='artifact-dialog';dialog.innerHTML=`<div class="artifact-heading"><h2>Saved files</h2><button class="iconbtn" data-close aria-label="Close">${icon('cross',18)}</button></div><p class="artifact-feedback" role="status">Loading files…</p><div class="artifact-layout"><nav class="artifact-list" aria-label="Artifact files"></nav><div class="artifact-content"><div class="json-toolbar"><span data-artifact-name>Select a file</span><button class="inlinebtn" data-artifact-copy disabled>Copy</button><button class="inlinebtn" data-artifact-download disabled>Download</button></div><pre class="artifact-preview" tabindex="0"></pre></div></div>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();opener?.focus()});let current=null;const feedback=dialog.querySelector('.artifact-feedback'),preview=dialog.querySelector('.artifact-preview');dialog.querySelector('[data-artifact-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(current.text);feedback.textContent='Copied'}catch{feedback.textContent='Select the preview to copy it.'}};dialog.querySelector('[data-artifact-download]').onclick=()=>{if(current)downloadFile(Uint8Array.from(atob(current.base64),c=>c.charCodeAt(0)),current.name.split('/').pop(),'application/octet-stream')};try{const data=await localRequest('artifacts',{id,key});if(!dialog.isConnected)return;feedback.textContent=data.truncated?'Showing the first 1,000 files.':data.files.length?'':'No saved output files.';dialog.querySelector('.artifact-list').innerHTML=data.files.map(file=>`<button data-file="${esc(file.name)}"><span>${esc(file.name)}</span><small>${f(file.size/1024,1)} KB</small></button>`).join('');let request=0;dialog.querySelectorAll('[data-file]').forEach(button=>button.onclick=async()=>{const sequence=++request;current=null;dialog.querySelectorAll('[data-artifact-copy],[data-artifact-download]').forEach(b=>b.disabled=true);preview.textContent='Loading…';dialog.querySelector('[data-artifact-name]').textContent=button.dataset.file;dialog.querySelectorAll('[data-file]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});try{const file=await localRequest('artifact',{id,key,name:button.dataset.file});if(sequence!==request||!dialog.isConnected)return;current=file;if(file.text===null)preview.textContent='Binary file · Download to open';else preview.innerHTML='<code>'+highlightArtifact(file.name,file.text.slice(0,200000))+'</code>';feedback.textContent=file.text?.length>200000?'Preview shortened. Download contains the complete file.':'';dialog.querySelector('[data-artifact-copy]').disabled=file.text===null;dialog.querySelector('[data-artifact-download]').disabled=false}catch(error){if(sequence===request){preview.textContent='';feedback.textContent=error.message}}});dialog.querySelector('[data-file]')?.click();}catch(error){feedback.textContent=error.message}}
function evaluationReadiness(){if(workspaceLocked())return ['Clone this run to execute a new evaluation.'];const services=s.platforms.filter(p=>p.enabled),problems=[];if(!bridgeReady)problems.push('Start the local companion.');else{if(services.some(p=>selectedModels(p).length>1)&&!localStatus?.multiModel)problems.push('Restart the updated local companion to run multiple models.');if(!localStatus?.dockerReady)problems.push('Start Docker.');if(localStatus?.credentialError)problems.push(localStatus.credentialError);for(const p of services){if(!(p.id in localRunners)){problems.push(`${p.name}: automatic execution is not supported. Remove it from this run in Set up.`);continue}const catalog=modelCatalogs.get(modelCatalogKey(p));if(!catalog||catalog.status!=='ready'||!selectedModels(p).length||selectedModels(p).some(model=>!catalog?.models?.some(m=>m.id===model)))problems.push(`${p.name}: choose available models in Set up and remove unavailable selections.`);const model=p.model||'',key=p.id==='opencode'?(model.startsWith('anthropic/')?'ANTHROPIC_API_KEY':model.startsWith('openai/')?'OPENAI_API_KEY':null):localRunners[p.id];if(!key)problems.push(`${p.name}: set an openai/model or anthropic/model identifier in Set up.`);else if(!localStatus?.configured?.[key])problems.push(`${p.name}: configure ${key} in Credentials.`)}}if(reviewEligible()&&runOptions().platformReview&&judgeState&&(!judgeState.configured||!judgeState.model))problems.push('Configure a judge in Settings or exclude platform review.');if(!services.length)problems.push('Select at least one service in Set up.');if(runOptions().pendingLiteCount)problems.push('Finish preparing or cancel SWE-bench Lite in Tasks & Benchmarks.');if(runOptions().integratedBenchmarks.length&&!localStatus?.integratedBenchmarks)problems.push('Restart the updated local companion to run SWE-bench Lite.');if(!s.tasks.length&&!runOptions().benchmarkPaths.length&&!runOptions().integratedBenchmarks.length)problems.push('Define a task or add a benchmark pack.');if(['preparing','running'].includes(localStatus?.job?.status))problems.push('An evaluation is already running.');return problems}
function refreshEvaluationReadiness(){const issues=evaluationReadiness(),active=workspaceLocked()||['preparing','running'].includes(localStatus?.job?.status);if($('#run-readiness-row'))$('#run-readiness-row').hidden=active;if($('#run-controls'))$('#run-controls').hidden=active;if($('#evaluation-readiness'))$('#evaluation-readiness').innerHTML=`<span class="status-led ${issues.length?'is-warning':'is-ready'}"></span><div><b>${issues.length?'Setup needs attention':'Ready to run'}</b>${issues.length&&!active?`<p>${esc(issues.join(' '))}</p>`:''}</div>`;if($('#start-evaluation'))$('#start-evaluation').disabled=!!issues.length||!$('#evaluation-consent')?.checked;}

