document.querySelectorAll('[data-include-suite]').forEach(el=>el.onchange=()=>{let all={};try{all=JSON.parse(localStorage.getItem('basis-evidence-exclusions')||'{}')}catch{}const id=currentEvaluation().id,excluded=new Set(all[id]||[]);el.checked?excluded.delete(el.dataset.includeSuite):excluded.add(el.dataset.includeSuite);all[id]=[...excluded];localStorage.setItem('basis-evidence-exclusions',JSON.stringify(all));render()});
