let workspaceReady=false,workspaceRun=null,workspaceRuns=[],workspaceSaveChain=Promise.resolve(),workspaceSaveError='',workspaceSaving=0,workspaceTimer=null,workspaceSearch='',workspaceFilter='all',workspaceBooting=false;
function workspaceLocked(){return workspaceReady&&workspaceRun&&workspaceRun.status!=='draft'}
function hydrateSetup(setup){const base=clone(demo);return {...base,...clone(setup),meta:{...base.meta,...setup.meta},org:{...base.org,...setup.org},weights:{...base.weights,...setup.weights},platforms:(setup.platforms||base.platforms).map(p=>({...base.platforms.find(x=>x.id===p.id),...p})),tasks:setup.tasks||[]}}
function workspaceChanges(){return workspaceRun?.status==='draft'&&workspaceRun.changes?.length?`<details class="workspace-change-summary"><summary>Changes from original · ${workspaceRun.changes.length}</summary><ul>${workspaceRun.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></details>`:''}
function workspaceStatus(status){return {draft:'Draft',preparing:'Preparing',running:'Running',completed:'Completed',partial:'Needs review',failed:'Failed',stopped:'Stopped',interrupted:'Interrupted'}[status]||status}
function workspaceBadge(status){return `<span class="workspace-status ${status}">${icon(status==='completed'?'check':status==='draft'?'copy':'clock',14)}${esc(workspaceStatus(status))}</span>`}
