async function activateWorkspace(run,destination){workspaceRun=run;s=hydrateSetup(run.setup);selected=s.platforms[0]?.id;evaluationSelected=run.id;resultsTab='results';fitSelected=null;liteState={status:'idle'};workspaceSaveError='';localStorage.setItem('basis-active-run',run.id);localStorage.setItem('basis-setup-migrated','true');page=destination||(run.status==='draft'?'gates':['preparing','running'].includes(run.status)?'record':'results');localStorage.setItem('basis-run-page',page);await loadEvaluationHistory();render();}
